SELECT column_name, COUNT(*) as non_null_count, COUNT(*) FILTER (WHERE value IS NULL) as null_count, ROUND(100.0 * COUNT(*) FILTER (WHERE value IS NOT NULL) / COUNT(*), 2) as non_null_percent FROM (SELECT 'Enrollment (K-12)' as column_name, "Enrollment (K-12)" AS value FROM frpm UNION ALL SELECT 'FRPM Count (K-12)', "FRPM Count (K-12)" AS value FROM frpm UNION ALL SELECT 'Free Meal Count (K-12)', "Free Meal Count (K-12)" AS value FROM frpm) columns GROUP BY column_name ORDER BY non_null_percent ASC;
